    with open(path, encoding="utf-8-sig", newline="") as handle:
        text = handle.read()
    header_end = len(text)
    for index, char in enumerate(text):
        if char in "\r\n":
            header_end = index
            break
    header_line = text[:header_end]
    delimiter = ","
    for candidate in (",", ";", "\t"):
        if candidate in header_line:
            delimiter = candidate
            break
    reader = csv.reader(text.splitlines(True) and __import__("io").StringIO(text, newline=""),
                        delimiter=delimiter, quotechar='"')
    header = None
    rows = []
    for cells in reader:
        cells = [cell.strip() for cell in cells]
        if header is None:
            header = cells
            continue
        if not any(cells):
            continue
        row = {}
        for name, cell in zip(header, cells):
            if name not in row:
                row[name] = cell if cell != "" else None
        rows.append(row)
    return rows


def parse_offset(text):
    sign = -1 if text[0] == "-" else 1
    hours, minutes = text[1:].split(":")
    return timezone(sign * timedelta(hours=int(hours), minutes=int(minutes)))


def parse_time(value, meta):
    if meta.get("submitted_format") == "local":
        moment = datetime.strptime(value, "%Y-%m-%d %H:%M:%S")
        return moment.replace(tzinfo=parse_offset(meta["utc_offset"]))
    match = re.match(r"^(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d):(\d\d)(\.\d+)?(Z|[+-]\d\d:\d\d)$", value)
    year, month, day, hour, minute, second = (int(match.group(i)) for i in range(1, 7))
    micro = int(round(float(match.group(7)) * 1000000)) if match.group(7) else 0
    zone = timezone.utc if match.group(8) == "Z" else parse_offset(match.group(8))
    return datetime(year, month, day, hour, minute, second, micro, tzinfo=zone)


def parse_duration(value, meta):
    if meta.get("duration_format") == "clock":
        total = 0
        for part in value.split(":"):
            total = total * 60 + int(part)
        return total
    return int(float(value))


def to_code(value, recode):
    if recode is not None:
        return recode[value]
    return int(value)


