        if name.endswith(".csv") and os.path.isfile(path):
            rows.extend(read_export(path))

    stats = {key: {"rows": 0, "duplicates": 0, "short_partials": 0, "speeders": 0,
                   "complete": 0, "partial": 0} for key in version_keys}
