    for row in rows:
        version = row.get("form_version")
        if version not in versions:
            continue
        meta = versions[version]["meta"]
        stats[version]["rows"] += 1
        submitted = row.get(meta["submitted"])
        duration = row.get(meta["duration"])
        last_page = row.get(meta["last_page"])
        records.append({
            "row": row,
            "version": version,
            "id": row.get(meta["id"]),
            "complete": row.get(meta["status"]) == meta["complete"],
            "time": parse_time(submitted, meta) if submitted is not None else None,
