            for option in question["options"]:
                if row.get(entry["columns"].get(str(option["code"]), "\0")) == "1":
                    chosen.append(option["code"])
        else:
            value = row.get(entry["column"])
            if value is not None:
                for element in value.split(entry["separator"]):
                    element = element.strip()
                    if element:
                        code = to_code(element, recode)
                        if code not in chosen:
                            chosen.append(code)
