            question = qmap[question_id]
            asked[question_id] = False
            result = False
            entry = question["versions"].get(record["version"])
            if entry is not None and (record["complete"] or entry["page"] <= record["last_page"]):
                condition = question.get("ask_if")
                ok = True
                if condition:
                    ok = False
                    if resolve(condition["question"]):
                        given = answers.get(condition["question"])
                        if given is not None:
                            if isinstance(given, list):
                                ok = any(c in condition["codes"] for c in given)
                            else:
                                ok = given in condition["codes"]
                if ok:
