            option = next((o for o in question["options"] if o["code"] == code), None)
            if option is not None and option.get("missing"):
                return None
            return code
        if qtype == "age":
            value = row.get(entry["column"])
            if value is None:
                return None
            source = entry.get("source")
            if source == "band":
                return to_code(value, recode)
            age = int(value)
            if source == "birth_year":
                age = reference_year - age
            for band in question["bands"]:
                if band["min"] <= age <= band["max"]:
                    return band["code"]
            return None
        chosen = []
        if "columns" in entry:
            for option in question["options"]:
                if row.get(entry["columns"].get(str(option["code"]), "\0")) == "1":
                    chosen.append(option["code"])
        else:
            value = row.get(entry["column"])
            if value is not None:
                for element in value.split(entry["separator"]):
                    element = element.strip()
                    if element:
                        code = to_code(element, recode)
                        if code not in chosen:
                            chosen.append(code)
        if not chosen:
            return None
        flags = {o["code"]: o for o in question["options"]}
        exclusive = [c for c in chosen if flags[c].get("exclusive")]
        others = [c for c in chosen if not flags[c].get("exclusive")]
        if exclusive and others:
            chosen = others
        elif len(exclusive) >= 2:
            return None
        chosen = [c for c in chosen if not flags[c].get("missing")]
        return chosen or None

    for record in respondents:
        answers = {}
        asked = {}

        def resolve(question_id):
            if question_id in asked:
                return asked[question_id]
            question = qmap[question_id]
            asked[question_id] = False
            result = False
            entry = question["versions"].get(record["version"])
            if entry is not None and (record["complete"] or entry["page"] <= record["last_page"]):
                condition = question.get("ask_if")
                ok = True
                if condition:
                    ok = False
                    if resolve(condition["question"]):
                        given = answers.get(condition["question"])
                        if given is not None:
                            if isinstance(given, list):
                                ok = any(c in condition["codes"] for c in given)
                            else:
                                ok = given in condition["codes"]
                if ok:
                    result = True
                    answers[question_id] = read_answer(question, record)
            asked[question_id] = result
            return result

        for question in questions:
            resolve(question["id"])
        record["answers"] = {qid: answers[qid] for qid in answers if answers[qid] is not None}

    count = len(respondents)
    weights = [1.0] * count
    dims = []
    for dim in weighting["dimensions"]:
        qid = dim["question"]
        present = {r["answers"].get(qid) for r in respondents}
        targets = {int(k): v for k, v in dim["targets"].items() if int(k) in present}
        total = sum(targets.values())
        if not targets or total == 0:
            continue
        shares = {c: v / total for c, v in targets.items()}
        cats = [r["answers"].get(qid) if r["answers"].get(qid) in shares else None
                for r in respondents]
        dims.append((shares, cats))
    for _ in range(int(weighting["max_iterations"])):
        converged = True
        for shares, cats in dims:
            sums = {c: 0.0 for c in shares}
            for index, cat in enumerate(cats):
                if cat is not None:
                    sums[cat] += weights[index]
            total = sum(sums.values())
            factors = {c: shares[c] * total / sums[c] for c in shares if sums[c] > 0}
            for factor in factors.values():
                if abs(factor - 1) > weighting["tolerance"]:
                    converged = False
            for index, cat in enumerate(cats):
                if cat in factors:
                    weights[index] *= factors[cat]
        if converged:
            break
    if count:
        mean = sum(weights) / count
        high, low = weighting["cap"] * mean, weighting["floor"] * mean
        weights = [min(max(w, low), high) for w in weights]
        scale = count / sum(weights)
        weights = [w * scale for w in weights]

    def rnd(value):
        return None if value is None else round(value, 2)

    summary = {
        "versions": [dict(version=key, **stats[key]) for key in version_keys],
        "respondents": count,
        "effective_n": rnd(sum(weights) ** 2 / sum(w * w for w in weights)) if count else None,
        "weight_min": rnd(min(weights)) if count else None,
        "weight_max": rnd(max(weights)) if count else None,
    }

    def options_of(question):
        if question["type"] == "age":
            return [dict(b) for b in question["bands"]]
        return question["options"]

    columns = [("total", None, None)]
    for qid in plan["banner"]:
        for option in options_of(qmap[qid]):
            if not option.get("missing"):
                columns.append((f"{qid}:{option['code']}", qid, option["code"]))

    tables = []
    for table in plan["tables"]:
        qid = table["question"]
        question = qmap[qid]
        is_multi = question["type"] == "multi"
        options = [o for o in options_of(question) if not o.get("missing")]
        scores = {o["code"]: o.get("score") for o in options}
        base_idx = [i for i, r in enumerate(respondents) if qid in r["answers"]]
        out_columns = []
        for column_id, banner_q, banner_code in columns:
            members = [i for i in base_idx
                       if banner_q is None or respondents[i]["answers"].get(banner_q) == banner_code]
            weighted = sum(weights[i] for i in members)
            values = {}
            if not members:
                for option in options:
                    values[str(option["code"])] = None
                for net in table.get("nets", []):
                    values[net["id"]] = None
                if table.get("mean"):
                    values["mean"] = None
                out_columns.append({"column": column_id, "base": 0, "weighted_base": 0,
                                    "values": values})
                continue

            def has(index, codes):
                answer = respondents[index]["answers"][qid]
                if is_multi:
                    return any(c in answer for c in codes)
                return answer in codes

            for option in options:
                values[str(option["code"])] = rnd(
                    100 * sum(weights[i] for i in members if has(i, [option["code"]])) / weighted)
            for net in table.get("nets", []):
                values[net["id"]] = rnd(
                    100 * sum(weights[i] for i in members if has(i, net["codes"])) / weighted)
            if table.get("mean"):
                values["mean"] = rnd(sum(weights[i] * scores[respondents[i]["answers"][qid]]
                                         for i in members) / weighted)
            out_columns.append({"column": column_id, "base": len(members),
                                "weighted_base": rnd(weighted), "values": values})
        tables.append({"table": table["id"], "columns": out_columns})

    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump({"survey": codebook["survey"], "summary": summary, "tables": tables}, handle,
                  indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
